// ==========================================================================
//  CONFIG — the only node you normally need to edit.
//  Everything downstream reads from here: competitors, sources, thresholds,
//  model choice and the full prompt text (so prompts are visible in the demo).
// ==========================================================================
const settings = {
  version: '1.15',
  reportTitle: 'Cellular IoT Competitor Intelligence',
  cadence: 'Weekly',
  lookbackDays: 7,
  significanceThreshold: 3,
  selfNames: ['Cavli'],          // our own company: routed to 'Cavli in the news', never treated as a competitor
  filterMode: 'ai',              // 'ai'    = AI judges relevance; code only does date window, dedupe, caps
                                 // 'rules' = also apply keyword/URL/language filters before AI
  englishOnly: true,             // drop titles that are mostly non-Latin script      // 1–5. Items below this go to the appendix only
  maxItemsPerCompetitor: 30,     // cap after dedupe, before AI (cost control)
  maxMarketItems: 15,
  triageBatchSize: 12,           // news items per LLM triage call
  useRunHistory: true,           // cross-run dedupe — applied ONLY on scheduled runs; manual runs always give a full report
  resetHistory: false,           // set true for one run to wipe the memory of already-reported stories
  historyRetentionDays: 60,
  senderEmail: 'Competitor Intelligence <your-sender@gmail.com>',  // MUST match the SMTP credential's User (Gmail sends only as itself)
  reportRecipients: 'you@example.com',
  reviewerEmail: 'you@example.com',
  tavily: {
    enabled: true,               // extra search source + full-text enrichment
    maxResultsPerQuery: 10,
    enrichMinSignificance: 4,    // fetch full article text for items at/above this
    maxEnrich: 10,               // cost cap (Tavily extract: ~1 credit per 5 URLs)
  },
  llm: {
    // Any OpenAI-compatible Chat Completions endpoint works:
    //   OpenAI  -> https://api.openai.com/v1
    //   Gemini  -> https://generativelanguage.googleapis.com/v1beta/openai
    //   Groq / OpenRouter / local vLLM / Ollama (/v1) also work
    baseUrl: 'https://api.openai.com/v1',
    triageModel: 'gpt-6-luna',    // GPT-6 family (Sep 2026): cheap, fast reasoning model for high-volume triage
    writerModel: 'gpt-6.1-sol',   // GPT-6.1 Sol (Sep 2026): strong reasoning + writing for the final brief
    temperature: null,            // reasoning models may reject temperature; set a number only for non-reasoning models
                                  // Fallback if your account lacks access: 'gpt-5.6-luna' / 'gpt-5.6-sol'
  },
};

// Edit to match Cavli's public positioning (website / LinkedIn "About").
const companyContext =
  'Cavli Wireless is a cellular IoT company with engineering in Kochi, India. ' +
  'It designs cellular IoT modules (LTE Cat-M / NB-IoT, LTE Cat-1 / Cat-1 bis, Cat-4 and 5G) ' +
  'with integrated eSIM connectivity, and offers the Cavli Hubble platform for global ' +
  'connectivity and device management. Key buyers are IoT device OEMs in asset tracking, ' +
  'smart metering, telematics, POS, healthcare and industrial IoT.';

const competitors = [
  { id: 'QUE', officialDomains: ['quectel.com'], name: 'Quectel',
    aliases: ['Quectel'],
    query: 'Quectel',
    focus: 'Largest cellular IoT module vendor by volume; broad LTE/5G/RedCap and GNSS portfolio.' },
  { id: 'TEL', officialDomains: ['telit.com', 'telitcinterion.com'], name: 'Telit Cinterion',
    aliases: ['Telit Cinterion', 'Telit', 'Cinterion'],
    query: '"Telit Cinterion" OR "Telit" IoT',
    focus: 'Modules, eSIM/iSIM connectivity and IoT services; strong in industrial and enterprise.' },
  { id: 'FIB', officialDomains: ['fibocom.com'], name: 'Fibocom',
    aliases: ['Fibocom'],
    query: 'Fibocom',
    focus: 'Cellular modules incl. 5G/RedCap and AI-capable smart modules; strong in automotive/FWA.' },
  { id: 'SEM', officialDomains: ['semtech.com', 'sierrawireless.com'], name: 'Semtech (Sierra Wireless)',
    aliases: ['Sierra Wireless', 'Semtech', 'AirPrime', 'AirLink'],
    query: '"Sierra Wireless" OR Semtech cellular OR Semtech IoT',
    focus: 'Owns Sierra Wireless modules, routers and connectivity. LoRa-only or non-IoT (e.g. data-centre) news is low relevance (max 2).',
    offTopic: 'LoRa|data cent(er|re)|SiGe|optical|PMIC|power management', onTopic: 'cellular|LTE|5G|AirLink|AirPrime|NB-IoT|LTE-M|module|router' },
  { id: 'NOR', officialDomains: ['nordicsemi.com'], name: 'Nordic Semiconductor',
    aliases: ['Nordic Semiconductor', 'nRF91', 'nRF9151', 'nRF9160', 'nRF9161'],
    query: '"Nordic Semiconductor" cellular OR nRF91',
    focus: 'Low-power LTE-M/NB-IoT SiPs (nRF91 series); competes for low-power tracker designs. Bluetooth/Wi-Fi-only news is low relevance (max 2).',
    offTopic: 'Bluetooth|BLE|Wi-?Fi|nRF54|nRF52|nRF53|nRF70|Matter|Thread|PMIC', onTopic: 'cellular|LTE|NB-IoT|LTE-M|nRF91|NTN|satellite' },
];

// Market-wide keywords: industry-feed items are kept if they mention a
// competitor OR one of these, so "other significant market developments" are covered.
const marketKeywords = ['cellular IoT', 'LTE-M', 'LTE Cat-M', 'Cat-M1', 'NB-IoT', 'RedCap',
  'Cat-1 bis', 'Cat 1bis', 'Cat-1bis', 'eSIM', 'iSIM', 'SGP.32', 'LPWA', 'LPWAN',
  'non-terrestrial', 'NTN', 'satellite IoT', 'IoT module', 'IoT connectivity', '3GPP Release'];

const marketQuery = '"cellular IoT" OR "IoT module" OR RedCap OR "NB-IoT" OR "LTE-M" OR "SGP.32"';

// Public RSS feeds of IoT trade publications. Verify each URL opens in a
// browser before the demo; add/remove freely (WordPress sites use /feed/).
const industryFeeds = [
  { name: 'IoT Business News', url: 'https://iotbusinessnews.com/feed/' },
];

// Noise filter: syndicated market-research ads, stock chatter, job posts.
const noisePatterns = [
  /\bmarket (size|share|report|research|analysis|outlook|forecast|trends?|insights?)\b/,
  /\bCAGR\b/,
  /\bforecast(ed)? (period|to|till|through|until) 20\d\d\b/,
  /\b(share|stock) price\b/,
  /\bshares? (rose|fell|jumped|dropped|gained|slipped|surged|tumbled|climbed)\b/,
  /\bprice target\b/,
  /\banalysts? (rating|upgrade|downgrade)s?\b/,
  /\b(top|key|leading) (players|companies|vendors|manufacturers) (in|of)\b/,
  /\b(job|career|hiring) (opening|opportunit|vacanc)/,
  /市場規模|市场规模|市場調査|年平均成長率/,
  /\b(estimates|earnings call transcript)\s*[–-]\s*[A-Z]{2,5}:\d+/,
].map(r => r.source);

// Non-news pages (docs, code, social profiles, support portals) — dropped by URL or title.
const junkUrlPatterns = [
  /linkedin\.com\/(company|in)\//, /facebook\.com/, /(twitter|x)\.com\//, /youtube\.com/, /instagram\.com/,
  /wikipedia\.org/, /github\.com|gitlab|git-master|\/-\/blob\//, /\/(docs?|documentation|manuals?|datasheets?|downloads?|support|resources|reference|careers|jobs|aussteller|exhibitors?)\//,
  /^https?:\/\/(developer|docs|source|support|forum|community)\./, /\.(pdf|zip)(\?|$)/,
].map(r => r.source);
const junkTitlePatterns = [
  /\b(user guide|user manual|hardware design|datasheet|release notes?|application note|reference manual|configuration templates?|getting started|faq)\b/,
  /\|\s*(company|home|about( us)?|exhibitor|profile|overview)\s*$/,
  /\.(h|c|py|js|json|xml)\b.*·/, /^[\w\s&-]{2,40}$/,   // bare page titles like "Telit Cinterion"
].map(r => r.source);
// Market items must ALSO contain one of these (stops "Redcap Tour Co." / clinical "REDCap").
const marketContext = /\b(IoT|M2M|cellular|module|modules|5G|LTE|eSIM|iSIM|operator|carrier|connectivity|3GPP|chipset)\b/.source;

// Sources treated as authoritative when picking the representative copy of a story.
const preferredDomains = ['quectel.com', 'telit.com', 'telitcinterion.com', 'fibocom.com',
  'semtech.com', 'sierrawireless.com', 'nordicsemi.com', 'businesswire.com',
  'prnewswire.com', 'globenewswire.com', 'gsma.com'];

// ------------------- RUN-TIME INPUT (form trigger) -----------------------
// Scheduled/manual runs use the defaults above. A run started from the
// "Run on Demand (Form)" trigger overrides competitors, lookback and recipient.
const trig = ($input.first() && $input.first().json) || {};
let runSource = trig['Competitors'] !== undefined ? 'form' : (trig.timestamp || trig['Day of week'] ? 'schedule' : 'manual');
if (runSource === 'form') {
  const used = new Set(['MKT', 'SEL']);
  const makeId = name => {
    const L = name.toUpperCase().replace(/[^A-Z]/g, '') || 'CMP';
    const cands = [L.slice(0, 3)];
    for (let i = 1; i < L.length; i++) for (let j = i + 1; j < L.length; j++) cands.push(L[0] + L[i] + L[j]);
    for (let k = 0; k < 26 * 26; k++) cands.push(L[0] + String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26)));
    const id = cands.find(c => c.length === 3 && !used.has(c)); used.add(id); return id;
  };
  const lines = String(trig['Competitors'] || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean).slice(0, 8);
  const custom = lines.map(line => {
    const [namePart, aliasPart = '', domainPart = ''] = line.split('|').map(x => x.trim());
    const known = competitors.find(c => c.name.toLowerCase() === namePart.toLowerCase() || c.aliases.some(a => a.toLowerCase() === namePart.toLowerCase()));
    if (known && !aliasPart && !domainPart) { used.add(known.id); return known; }   // reuse curated settings
    const aliases = [namePart, ...aliasPart.split(',').map(a => a.trim()).filter(Boolean)];
    return { id: makeId(namePart), name: namePart, aliases,
      officialDomains: domainPart.split(',').map(d => d.trim().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '')).filter(Boolean),
      query: aliases.map(a => (/\s/.test(a) ? `"${a}"` : a)).join(' OR '),
      focus: 'Competitor entered via the on-demand form; judge relevance to cellular IoT.' };
  });
  if (custom.length) competitors.splice(0, competitors.length, ...custom);
  const lb = Number(trig['Lookback days']); if (lb >= 1 && lb <= 31) settings.lookbackDays = Math.round(lb);
  if (trig['Send report to']) settings.reportRecipients = String(trig['Send report to']).trim();
}

// ----------------------------- PROMPTS -----------------------------------
const triageSystem = `You are a senior competitive-intelligence analyst for the cellular IoT industry, working for the marketing team of the company described below.

COMPANY CONTEXT
${companyContext}

TASK
You receive a batch of news items collected automatically from public sources. For EACH item decide whether it is a genuine, relevant development and score its significance to our company. Work ONLY from the title and snippet provided. Never add facts, numbers, names or dates that are not present in the item.

RELEVANCE — set "relevant": false when:
- the competitor is only mentioned in passing (e.g. one name in a long list);
- it is stock-price commentary, investor-ownership filings or a syndicated "market research report" advert;
- the name refers to a different entity (namesake);
- the item repeats another item in the same batch (also set "duplicate_of" to that item's id);
- it is not a news item: documentation, user guides, datasheets, release notes, code/repository files, support or download pages, social-media profiles, company "about" or exhibitor pages, job postings;
- it is about something unrelated that merely shares a word (e.g. "REDCap" research software, a company named "Redcap Tour", a non-IoT business unit) or is a market-research advert in any language;
- for market-wide items (no competitor), it does not concern cellular IoT connectivity, modules, chipsets, standards or operators.

CATEGORY (exactly one)
product_launch | partnership | technology | corporate | marketing_positioning | financial | market_signal | other
- product_launch: new/updated modules, chipsets, platforms, SKUs, dev kits
- partnership: alliances, distribution, operator/carrier deals, ecosystem integrations, named design wins
- technology: certifications, standards (RedCap, LTE-M, NB-IoT, eSIM/SGP.32, iSIM, NTN), R&D, benchmarks
- corporate: M&A, leadership changes, restructuring, facilities, regional expansion, litigation
- marketing_positioning: campaigns, messaging shifts, trade-show presence, awards, thought leadership, pricing moves
- financial: earnings, guidance, funding (not stock-price chatter)
- market_signal: industry developments without a specific competitor that affect the cellular IoT market
- other: anything else

COMPETITOR FIELD
Set "competitor" to the company the item is actually ABOUT (one of the tracked competitors, exact name), not merely the one in the search hint. If it is about another company or the market in general, use null. If it is about our own company, use "SELF".

SIGNIFICANCE (integer 1–5, from OUR company's point of view)
5 = could change competitive dynamics now: M&A, new module family in our segments, major operator/hyperscaler partnership, entry into India or our key markets, aggressive pricing, major certification win.
4 = clearly important: notable product update, new certification, named strategic customer/partner, new region, C-level change.
3 = worth knowing: incremental product news, trade-show announcements, case studies, ecosystem integrations.
2 = low: generic marketing content, awards, webinars, minor blog posts.
1 = negligible.
Calibration: use the full scale — most weeks should contain some 4s. Legal action between major module vendors, quarterly results showing a sharp profit or revenue swing, new module families, and moves into India are 4 or 5.
Market research: market-size projections, forecasts and "key players" lists from research firms are significance 2 at most, even if they name competitors.
Recency: if the item only re-describes products launched long ago, is an evergreen blog/explainer, a teardown of an older product, or a reseller/distributor listing, cap significance at 2.
Source quality: social-media posts (LinkedIn, Facebook, X) by third parties are weak evidence — confidence "low" and significance at most 2 unless the post is from the competitor's official account announcing something new.

OUTPUT
Return ONLY a JSON object, no prose, no markdown fences:
{"items":[{
  "id": "<item id exactly as given>",
  "relevant": true,
  "competitor": "<competitor name, or null for market-wide items>",
  "category": "<one category>",
  "significance": 3,
  "significance_rationale": "<max 25 words>",
  "summary": "<max 40 words, neutral, facts from the item only>",
  "implication_for_us": "<max 30 words: why this matters to our company, or 'Limited direct impact'>",
  "confidence": "high | medium | low",
  "evidence_quote": "<short phrase copied VERBATIM from the title or snippet that supports the summary>",
  "duplicate_of": null
}]}
Return exactly one object per input item, in the same order. Use confidence "low" when the snippet is too thin to be sure.`;

const writerSystem = `You are the editor of a recurring competitor-intelligence brief for the marketing and leadership team of the company described below. Your reader is busy: be concise, specific and decision-oriented.

COMPANY CONTEXT
${companyContext}

INPUT
A JSON list of pre-filtered, pre-scored developments. Each has an "id" (e.g. "QUE-3"), competitor, category, significance (1–5), summary, implication and source. High-significance items may include "article_excerpt": the first part of the full article text. When present, prefer it over the summary for concrete details (product names, partners, regions, specs), but still state only what it says.

RULES
1. Use ONLY the developments provided. Do not add outside knowledge, numbers or claims.
2. Every statement must be traceable: cite item ids in square brackets, e.g. "Quectel expanded its RedCap line [QUE-2]".
3. Only reference ids that appear in the input. Never invent ids.
4. Merge items describing the same event into one development (list the others in related_ids). If one event involves two competitors (e.g. a lawsuit), describe it once under the competitor that initiated it and mention it briefly in the other's summary.
5. Prefer concrete facts over adjectives. No hype, no speculation presented as fact.
6. Include every tracked competitor. If one has no items, set activity_level "none" and developments [].
7. Recommended actions must be practical for a marketing team (content, messaging, sales enablement, events, product-marketing follow-ups) and tied to specific ids.

OUTPUT — return ONLY this JSON object, no markdown fences:
{
  "headline": "<one sentence: the single most important takeaway this period>",
  "executive_summary": ["<3–5 bullets, each with [ID] citations>"],
  "competitors": [{
    "name": "<competitor name exactly as listed>",
    "activity_level": "high | medium | low | none",
    "summary": "<1–2 sentences>",
    "developments": [{
      "id": "<primary item id>",
      "related_ids": [],
      "headline": "<max 12 words>",
      "what_happened": "<max 35 words>",
      "why_it_matters": "<max 30 words, from our company's perspective>",
      "category": "<category>",
      "significance": 4
    }]
  }],
  "market_signals": [{"text": "<max 35 words>", "ids": ["<id>"]}],
  "themes": [{"theme": "<max 6 words>", "description": "<max 35 words>", "ids": ["<id>"]}],
  "recommended_actions": [{"action": "<max 25 words>", "owner": "Marketing | Product Marketing | Sales | Leadership", "priority": "high | medium | low", "ids": ["<id>"]}],
  "watchlist": ["<max 20 words: what to monitor next period>"]
}`;

const now = new Date();
return [{
  json: {
    runId: 'CI-' + now.toISOString().slice(0, 16).replace(/[-:T]/g, ''), runSource,
    runDate: now.toISOString(),
    periodStart: new Date(now.getTime() - settings.lookbackDays * 86400000).toISOString(),
    settings, companyContext, competitors, marketKeywords, marketQuery,
    industryFeeds, noisePatterns, preferredDomains, junkUrlPatterns, junkTitlePatterns, marketContext,
    prompts: { triageSystem, writerSystem },
  },
}];

// One request item per (competitor x source) + market-wide sources.
const cfg = $('Config').first().json;
const days = cfg.settings.lookbackDays;
const gnews = q => 'https://news.google.com/rss/search?q=' +
  encodeURIComponent(`${q} when:${days}d`) + '&hl=en-US&gl=US&ceid=US:en';
const bing = q => 'https://www.bing.com/news/search?q=' + encodeURIComponent(q) + '&format=rss&count=50';

const out = [];
for (const c of cfg.competitors) {
  out.push({ json: { sourceType: 'google_news', competitorId: c.id, label: `Google News · ${c.name}`, url: gnews(c.query) } });
  out.push({ json: { sourceType: 'bing_news', competitorId: c.id, label: `Bing News · ${c.name}`, url: bing(c.query) } });
  for (const f of (c.extraFeeds || [])) {
    out.push({ json: { sourceType: 'company_feed', competitorId: c.id, label: `${f.name}`, url: f.url } });
  }
}
out.push({ json: { sourceType: 'google_news', competitorId: null, label: 'Google News · Market', url: gnews(cfg.marketQuery) } });
for (const f of cfg.industryFeeds) {
  out.push({ json: { sourceType: 'industry_feed', competitorId: null, label: f.name, url: f.url } });
}
return out;

// Parse RSS 2.0 / Atom XML returned by "Fetch Feeds" into normalized article items.
// No external libraries: robust regex parsing of <item>/<entry> blocks.
const cfg = $('Config').first().json;
const inputs = $input.all();

function pair(node, i) {
  try { const p = $(node).itemMatching(i); if (p && p.json) return p.json; } catch (e) {}
  const all = $(node).all();
  return (all[i] && all[i].json) || {};
}
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', mdash: '—',
  ndash: '–', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', trade: '™', reg: '®', copy: '©' };
const decode = (s = '') => s
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
  .replace(/&([a-z]+);/gi, (m, n) => (ENT[n.toLowerCase()] !== undefined ? ENT[n.toLowerCase()] : m));
const cdata = (s = '') => s.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1');
const clean = (s = '') => decode(decode(cdata(s)).replace(/<[^>]+>/g, ' ')).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
function getTag(block, name) {
  const re = new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + name + '>', 'i');
  const m = block.match(re);
  return m ? cdata(m[1]).trim() : '';
}
function getAttr(block, name, attr) {
  const re = new RegExp('<' + name + '\\s[^>]*?' + attr + '="([^"]*)"', 'i');
  const m = block.match(re);
  return m ? decode(m[1]) : '';
}
// Sandbox-safe URL helpers (n8n's Code sandbox may not provide the URL class)
function parseUrl(u) {
  const m = String(u || '').trim().match(/^([a-z][a-z0-9+.-]*):\/\/([^\/?#]*)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  const host = m[2].replace(/^[^@]*@/, '').replace(/:\d+$/, '').toLowerCase();
  return { host, domain: host.replace(/^www\./, ''), path: m[3] || '/', search: m[4] || '' };
}
function queryParam(search, key) {
  const m = String(search || '').match(new RegExp('[?&]' + key + '=([^&#]*)', 'i'));
  if (!m) return null;
  try { return decodeURIComponent(m[1].replace(/\+/g, ' ')); } catch (e) { return m[1]; }
}
function resolveUrl(link) {
  const u = parseUrl(link);
  if (u && /(^|\.)bing\.com$/.test(u.host)) { const real = queryParam(u.search, 'url'); if (real && /^https?:\/\//i.test(real)) return real; }
  return link;
}
function domainOf(url) { const u = parseUrl(url); return u ? u.domain : ''; }

const out = [];
for (let i = 0; i < inputs.length; i++) {
  const src = pair('Build Source Requests', i);
  const body = inputs[i].json.body;
  if (typeof body !== 'string' || !body.length) continue;           // fetch failed — reported in QC
  const blocks = body.match(/<item[\s>][\s\S]*?<\/item>/gi) || body.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  for (const b of blocks) {
    let title = clean(getTag(b, 'title'));
    if (!title) continue;
    const rawLink = decode(getTag(b, 'link')) || getAttr(b, 'link', 'href');
    const url = resolveUrl(rawLink.trim());
    const publisher = clean(getTag(b, 'source')) || clean(getTag(b, 'News:Source')) || src.label || '';
    const publisherUrl = getAttr(b, 'source', 'url');
    if (publisher && title.endsWith(' - ' + publisher)) title = title.slice(0, -(publisher.length + 3)).trim();
    let snippet = clean(getTag(b, 'description') || getTag(b, 'summary') || getTag(b, 'content:encoded'));
    // Google News descriptions just repeat "title publisher" — drop that echo
    if (snippet.startsWith(title)) snippet = snippet.slice(title.length).trim();
    if (publisher && snippet === publisher) snippet = '';
    const pub = getTag(b, 'pubDate') || getTag(b, 'published') || getTag(b, 'updated') || getTag(b, 'dc:date');
    const ts = Date.parse(pub);
    out.push({ json: {
      sourceType: src.sourceType, sourceLabel: src.label, feedCompetitorId: src.competitorId || null,
      title, snippet: snippet.slice(0, 600), url,
      publisher, publisherDomain: domainOf(publisherUrl) || domainOf(url),
      publishedAt: isNaN(ts) ? null : new Date(ts).toISOString(), ts: isNaN(ts) ? null : ts,
    } });
  }
}
return out;

// Tavily search queries: (a) news search per competitor, (b) competitor's own
// newsroom/website restricted via include_domains, (c) one market-wide query.
const cfg = $('Config').first().json;
const T = cfg.settings.tavily;
if (!T || !T.enabled) return [{ json: { skip: true } }];
const tr = cfg.settings.lookbackDays <= 1 ? 'day' : cfg.settings.lookbackDays <= 7 ? 'week' : 'month';
const out = [];
for (const c of cfg.competitors) {
  out.push({ json: { competitorId: c.id, label: `Tavily news · ${c.name}`, body: {
    query: `${c.name} cellular IoT news`, topic: 'news', days: cfg.settings.lookbackDays,
    max_results: T.maxResultsPerQuery, search_depth: 'basic' } } });
  if ((c.officialDomains || []).length) out.push({ json: { competitorId: c.id, label: `Tavily newsroom · ${c.name}`, body: {
    query: `${c.name} announces new product partnership`, topic: 'general', time_range: tr,
    include_domains: c.officialDomains, max_results: T.maxResultsPerQuery, search_depth: 'basic' } } });
}
out.push({ json: { competitorId: null, label: 'Tavily news · Market', body: {
  query: 'cellular IoT module RedCap NB-IoT LTE-M eSIM news', topic: 'news', days: cfg.settings.lookbackDays,
  max_results: T.maxResultsPerQuery, search_depth: 'basic' } } });
return out;

// Combine RSS articles with Tavily search results into one normalized list.
const rss = $('Parse & Normalize Feeds').all().map(i => i.json).filter(x => x && x.title);
const inputs = $input.all();
function pair(node, i) {
  try { const p = $(node).itemMatching(i); if (p && p.json) return p.json; } catch (e) {}
  const all = $(node).all(); return (all[i] && all[i].json) || {};
}
// Sandbox-safe URL helpers (n8n's Code sandbox may not provide the URL class)
function parseUrl(u) {
