const tav = [];
for (let i = 0; i < inputs.length; i++) {
  const r = inputs[i].json || {};
  if (!Array.isArray(r.results)) continue;               // skipped or failed — reported in QC
  const q = pair('Build Tavily Queries', i);
  for (const x of r.results) {
