const cfg = $('Config').first().json;
const S = cfg.settings;
const raw = $input.all().map(i => i.json).filter(x => x && x.title);
const stats = { nodeVersion: '1.15', collected: raw.length, droppedOffTopic: 0, droppedNoise: 0, droppedNonNews: 0, droppedLanguage: 0, droppedStale: 0, mergedDuplicates: 0, droppedOverCap: 0 };

const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const compRes = cfg.competitors.map(c => ({ id: c.id, re: new RegExp('(^|[^a-z0-9])(' + c.aliases.map(esc).join('|') + ')(?![a-z0-9])', 'i') }));
const marketRe = new RegExp('(^|[^a-z0-9])(' + cfg.marketKeywords.map(esc).join('|') + ')(?![a-z0-9])', 'i');
const noiseRes = cfg.noisePatterns.map(p => new RegExp(p, 'i'));
const junkUrlRes = (cfg.junkUrlPatterns || []).map(p => new RegExp(p, 'i'));
const junkTitleRes = (cfg.junkTitlePatterns || []).map(p => new RegExp(p, 'i'));
const ctxRe = new RegExp(cfg.marketContext || '.', 'i');
const latinShare = t => { const letters = t.match(/\p{L}/gu) || []; return letters.length ? (t.match(/[A-Za-z]/g) || []).length / letters.length : 1; };
const cutoff = Date.now() - S.lookbackDays * 86400000;
const STOP = new Set(['the','and','for','with','from','its','new','into','over','that','this','will','has','have','are','was','iot','announces','announced','launches','launched','unveils','introduces','says','after','amid','about','more','than','how','why','what','inc','ltd','co']);

