const kept = [];
for (const a of raw) {
  const text = a.title + ' ' + a.snippet;
  const rules = S.filterMode === 'rules';
  // Not an article: section/listing/index pages (mechanical check, all modes)
  { const u = parseUrl(a.url) || { path: '', search: '' }; if (/(\/list\.html?|\/(news|newsroom|newscenter|press|blog|media|events)\/?)$/i.test(u.path) || /\/(aussteller|exhibitors?|exhibitor-list|company-profile)\//i.test(u.path) || /[?&]page=\d/.test(u.search)) { stats.droppedNonNews = (stats.droppedNonNews || 0) + 1; continue; } }
  if (rules && noiseRes.some(r => r.test(text))) { stats.droppedNoise++; continue; }
  if (rules && (junkUrlRes.some(r => r.test(a.url || '')) || junkTitleRes.some(r => r.test(a.title)))) { stats.droppedNonNews++; continue; }
  if (rules && S.englishOnly && latinShare(a.title) < 0.6) { stats.droppedLanguage++; continue; }
  // Undated pages from company-website searches can be years old -> drop. Tavily news / RSS are date-bounded at source.
  if (!a.ts && a.sourceType === 'tavily' && !/^Tavily news ·/.test(a.sourceLabel || '')) { stats.droppedStale++; continue; }
  if (a.ts && a.ts < cutoff) { stats.droppedStale++; continue; }
  const mentions = compRes.filter(c => c.re.test(text)).map(c => c.id);
  let competitorId = null;
  if (a.feedCompetitorId) {
    const comp = cfg.competitors.find(c => c.id === a.feedCompetitorId) || {};
    const official = (comp.officialDomains || []).some(d => (a.publisherDomain || '').endsWith(d));
    if (rules && !mentions.includes(a.feedCompetitorId) && !official) { stats.droppedOffTopic++; continue; }
    competitorId = a.feedCompetitorId;
  } else if (mentions.length) {
    competitorId = mentions[0];
  } else if (rules && (!marketRe.test(text) || !ctxRe.test(text))) { stats.droppedOffTopic++; continue; }
  const preferred = [...cfg.preferredDomains, ...cfg.competitors.flatMap(c => c.officialDomains || [])].some(d => (a.publisherDomain || '').endsWith(d));
  kept.push({ ...a, competitorId, mentions, preferred, canon: canonical(a.url), tok: tokens(a.title) });
}

// Representative copy first: authoritative domain > has real snippet > earliest
const SOCIAL_D = /(^|\.)(linkedin|facebook|x|twitter|instagram|youtube|tiktok)\.com$/i;
for (const k of kept) k.nonSocial = SOCIAL_D.test(k.publisherDomain || '') ? 0 : 1;
kept.sort((x, y) => (y.nonSocial - x.nonSocial) || (y.preferred - x.preferred) || ((y.snippet.length > 80) - (x.snippet.length > 80)) || ((x.ts || 0) - (y.ts || 0)));

const clusters = [];
for (const a of kept) {
  const hit = clusters.find(c => c.competitorId === a.competitorId &&
    (c.canon === a.canon || jaccard(c.tok, a.tok) >= 0.55));
  if (hit) {
    stats.mergedDuplicates++;
    const newPublisher = a.canon !== hit.canon && (a.publisherDomain || a.publisher) !== (hit.publisherDomain || hit.publisher) &&
      !hit.alsoReportedBy.some(r => r.publisher === a.publisher);
    if (newPublisher) { hit.sourceCount++; hit.alsoReportedBy.push({ publisher: a.publisher, url: a.url }); }
    if (!hit.snippet && a.snippet) hit.snippet = a.snippet;
    for (const t of a.tok) hit.tok.add(t);
  } else {
    clusters.push({ ...a, sourceCount: 1, alsoReportedBy: [] });
  }
}

// Caps per competitor (cost control), most-corroborated & newest first
const groups = {};
for (const c of clusters) (groups[c.competitorId || 'MKT'] ||= []).push(c);
const out = [];
for (const [gid, list] of Object.entries(groups)) {
  list.sort((x, y) => (y.sourceCount - x.sourceCount) || ((y.ts || 0) - (x.ts || 0)));
  const cap = gid === 'MKT' ? S.maxMarketItems : S.maxItemsPerCompetitor;
  stats.droppedOverCap += Math.max(0, list.length - cap);
  list.slice(0, cap).forEach((c, idx) => {
    const fp = [...tokens(c.title)].sort().slice(0, 10).join('-');
    const { tok, canon, ...rest } = c;
    out.push({ json: { ...rest, id: `${gid}-${idx + 1}`, dedupeKey: `${gid}|${fp}`, competitorName:
      (cfg.competitors.find(x => x.id === c.competitorId) || {}).name || 'Market', pipelineStats: stats } });
  });
}
stats.afterFilterDedupe = out.length;
