// Cross-run memory: skip stories already reported in previous runs.
// Uses workflow static data -> persists for ACTIVE (scheduled) executions;
// manual test runs do not save it, so demos always show a full report.
// Keys are only committed after a successful report (see "Render Report").
const cfg = $('Config').first().json;
const items = $input.all().map(i => i.json).filter(x => x && x.id);
const store = $getWorkflowStaticData('global');
if (cfg.settings.resetHistory) store.seenStories = {};
const mode = (typeof $execution !== 'undefined' && $execution.mode) || 'production';
// Memory applies ONLY to the weekly schedule. Manual and form runs always return a full report.
const applyHistory = cfg.settings.useRunHistory && cfg.runSource === 'schedule' && mode !== 'test' && mode !== 'manual';
const seen = applyHistory ? (store.seenStories || {}) : {};
let skipped = 0;
const out = [];
for (const it of items) {
  if (applyHistory && seen[it.dedupeKey]) { skipped++; continue; }
  out.push({ json: { ...it, pipelineStats: { ...it.pipelineStats, skippedSeenInPreviousRuns: skipped } } });
}
// stamp final skipped count on every item
for (const o of out) o.json.pipelineStats.skippedSeenInPreviousRuns = skipped;
