// Pack items into LLM triage batches with compact, id-tagged prompts.
const cfg = $('Config').first().json;
const items = $input.all().map(i => i.json).filter(x => x && x.id);
const size = cfg.settings.triageBatchSize;

const ref = cfg.competitors.map(c => `- ${c.id} = ${c.name} (aliases: ${c.aliases.join(', ')}). ${c.focus}`).join('\n');
const batches = [];
for (let i = 0; i < Math.max(items.length, 1); i += size) batches.push(items.slice(i, i + size));

return batches.map((b, bi) => {
  const lines = b.map(it => JSON.stringify({
    id: it.id, competitor_hint: it.competitorName, title: it.title, snippet: it.snippet.slice(0, 450),
    publisher: it.publisher, date: (it.publishedAt || '').slice(0, 10), corroborating_sources: it.sourceCount,
  }));
  const userPrompt = `Competitor reference:\n${ref}\n\nItems to evaluate (${b.length}):\n` +
    (lines.length ? lines.join('\n') : '(no new items this period — return {"items":[]})');
  return { json: { batchIndex: bi, items: b, userPrompt, empty: b.length === 0 } };
});

// Parse + validate AI triage output. Quality controls:
//  - strict JSON parse (fence-stripping), enum/range validation
//  - evidence check: the quoted phrase must actually appear in the source text
//  - LLM-flagged duplicates merged; missing/failed items fall back to rules
const cfg = $('Config').first().json;
const S = cfg.settings;
const CATS = ['product_launch','partnership','technology','corporate','marketing_positioning','financial','market_signal','other'];
const responses = $input.all();
function pair(node, i) {
  try { const p = $(node).itemMatching(i); if (p && p.json) return p.json; } catch (e) {}
  const all = $(node).all(); return (all[i] && all[i].json) || {};
}
const strip = s => String(s || '').replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
