    [/\b(acquires|acquisition|merger|to acquire|takeover)\b/, 'corporate', 4],
    [/\b(partners? with|partnership with|collaborat\w* with|alliance with|selects|teams up with)\b/, 'partnership', 3],
    [/\b(launch(es|ed)?|unveil(s|ed)?|introduc(es|ed)|debuts?)\b.*\b(module|chipset|platform|router|sip|esim|redcap|5g|lte)\b/, 'product_launch', 3],
    [/\b(certif(ied|ication)|redcap|ntn|sgp\.32|isim)\b/, 'technology', 2],
    [/\b(appoints?|names .* (ceo|chief|president)|restructur\w*)\b/, 'corporate', 3],
    [/\b(revenue|earnings|guidance|funding)\b/, 'financial', 2],
  ];
  for (const [re, cat, sig] of rules) if (re.test(t)) return { category: cat, significance: sig };
  return { category: a.competitorId ? 'other' : 'market_signal', significance: 1 };
}

const scored = []; const failures = []; let evidenceMismatch = 0, missingFromAI = 0, llmDuplicates = 0, notRelevant = 0;
for (let i = 0; i < responses.length; i++) {
  const batch = pair('Build Triage Batches', i);
  const r = responses[i].json || {};
  let parsed = null;
  if (!batch.empty) {
    try { parsed = JSON.parse(strip(r.choices[0].message.content)); if (!Array.isArray(parsed.items)) throw new Error('missing items[]'); }
    catch (e) { failures.push({ stage: 'triage', batch: batch.batchIndex, error: (r.error && (r.error.message || JSON.stringify(r.error))) || e.message }); }
  }
  const byId = new Map(((parsed && parsed.items) || []).map(x => [String(x.id), x]));
  for (const a of (batch.items || [])) {
    const t = byId.get(a.id);
    if (!t) {
      missingFromAI++;
      const h = heuristic(a);
      if (S.filterMode !== 'rules') h.significance = Math.min(h.significance, 2);   // no AI + no rules -> appendix only
      scored.push({ ...a, triage: 'rules_fallback', relevant: true, ...h, rationale: 'Unverified — scored by keyword rules because the AI step failed.',
        summary: a.title, implication: 'Unverified (AI triage unavailable) — check the source.', confidence: 'low', evidenceOk: false, duplicateOf: null });
      continue;
