    const ev = evidenceOk(t.evidence_quote, a.title + ' ' + a.snippet);
    if (!ev) evidenceMismatch++;
    const conf = ['high', 'medium', 'low'].includes(t.confidence) ? t.confidence : 'low';
    scored.push({ ...a, triage: 'ai', relevant: t.relevant !== false,
      category: CATS.includes(t.category) ? t.category : 'other', significance: sig, aiCompetitor: t.competitor,
      rationale: String(t.significance_rationale || '').slice(0, 300), summary: String(t.summary || a.title).slice(0, 400),
      implication: String(t.implication_for_us || '').slice(0, 300),
      confidence: ev ? conf : 'low', evidenceOk: ev, evidenceQuote: String(t.evidence_quote || '').slice(0, 200),
      duplicateOf: t.duplicate_of && t.duplicate_of !== a.id ? String(t.duplicate_of) : null });
  }
}
// 1) Re-assign items to the company the AI says they are actually about
const findComp = name => { const n = String(name || '').toLowerCase().trim(); if (!n || n === 'null') return null;
  return cfg.competitors.find(c => [c.name, ...c.aliases].some(a => n.includes(a.toLowerCase()) || a.toLowerCase().includes(n))) || null; };
const selfRe = new RegExp('\\b(' + (cfg.settings.selfNames || ['Cavli']).join('|') + ')\\b', 'i');
let reassigned = 0;
for (const sc of scored) {
  if (selfRe.test(sc.title) || String(sc.aiCompetitor || '').toUpperCase() === 'SELF') { sc.isSelf = true; sc.competitorId = 'SELF'; sc.competitorName = 'Cavli'; continue; }
  if (sc.triage !== 'ai') continue;
  const c = findComp(sc.aiCompetitor);
  const newId = c ? c.id : null;
  if (newId !== sc.competitorId) { reassigned++; sc.competitorId = newId; sc.competitorName = c ? c.name : 'Market'; }
}
// 2) Social posts are weak evidence unless corroborated
const SOCIAL = /(^|\.)(linkedin|facebook|x|twitter|instagram|youtube|tiktok)\.com$/i;
// representative is social only when no non-social copy of the story exists (see Filter & Dedupe)
for (const sc of scored) if (SOCIAL.test(sc.publisherDomain || '') && sc.significance > 2) { sc.significance = 2; sc.socialCapped = true; }
// incidental mention: competitor not named in the headline of a third-party article -> not news about them
for (const sc of scored) {
  const c = cfg.competitors.find(x => x.id === sc.competitorId);
  if (!c || sc.significance <= 2) continue;
  const official = (c.officialDomains || []).some(d => (sc.publisherDomain || '').endsWith(d));
  const inTitle = c.aliases.some(al => new RegExp('(^|[^a-z0-9])' + al.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z0-9])', 'i').test(sc.title));
  // Exception: roundup/digest articles. If the AI rates it 4+ AND its verified evidence quote names the
  // competitor, the substantive claim is about them (e.g. "New US manufacturers…: Telit opens Bristol facility").
  const reAl = al => new RegExp('(^|[^a-z0-9])' + al.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z0-9])', 'i');
  const quoteNames = sc.evidenceOk && c.aliases.some(al => reAl(al).test(sc.evidenceQuote || ''));
  if (!official && !inTitle && !(sc.significance >= 4 && quoteNames)) { sc.significance = 2; sc.guardrailCapped = true; sc.incidental = true; }
}
// per-competitor off-topic guardrail (e.g. Nordic Bluetooth, Semtech LoRa) unless clearly cellular
for (const sc of scored) {
  const c = cfg.competitors.find(x => x.id === sc.competitorId);
  if (!c || !c.offTopic) continue;
  const t = sc.title + ' ' + sc.snippet;
  if (new RegExp(c.offTopic, 'i').test(t) && !new RegExp(c.onTopic || '$^', 'i').test(t) && sc.significance > 2) { sc.significance = 2; sc.guardrailCapped = true; }
}

// Old content republished/re-indexed: text mentions only past years, never the current one
const curYear = new Date(cfg.runDate).getUTCFullYear();
for (const sc of scored) {
  const yrs = ((sc.title + ' ' + sc.snippet).match(/\b(19|20)\d{2}\b/g) || []).map(Number).filter(y => y >= 1990 && y <= curYear + 1);
  if (yrs.length && Math.max(...yrs) < curYear && sc.significance > 2) { sc.significance = 2; sc.guardrailCapped = true; sc.datedContent = true; }
}
// Deterministic guardrails on top of AI judgement
for (const sc of scored) if (/\b(teardown|tear-down|market size|CAGR)\b|\bmarket\b[^.]{0,60}\b(reach|exceed|surpass|hit|cross|top)(es|ed|ing)?\s+(US)?\$/i.test(sc.title + ' ' + sc.snippet) && sc.significance > 2) { sc.significance = 2; sc.guardrailCapped = true; }

// Merge AI-identified duplicates into their primary item
const idx = new Map(scored.map(s => [s.id, s]));
for (const s of scored) {
  if (s.duplicateOf && idx.has(s.duplicateOf)) {
    const p = idx.get(s.duplicateOf);
    p.sourceCount += s.sourceCount; p.alsoReportedBy.push({ publisher: s.publisher, url: s.url });
    s.relevant = false; s.mergedInto = p.id; llmDuplicates++;
  }
}
// Unverifiable evidence -> downgrade one level (keeps it visible, avoids overstating)
for (const s of scored) if (s.triage === 'ai' && !s.evidenceOk && s.significance > 1) { s.significance -= 1; s.downgraded = true; }
for (const s of scored) if (!s.relevant && !s.mergedInto) notRelevant++;

const selfMentions = scored.filter(s => s.isSelf && s.relevant !== false);
const kept = scored.filter(s => !s.isSelf && s.relevant && s.significance >= S.significanceThreshold)
  .sort((a, b) => (b.significance - a.significance) || (b.sourceCount - a.sourceCount));

const writerInput = kept.map(k => ({ id: k.id, competitor: k.competitorName, category: k.category, significance: k.significance,
  summary: k.summary, implication: k.implication, publisher: k.publisher, date: (k.publishedAt || '').slice(0, 10),
  corroborating_sources: k.sourceCount, confidence: k.confidence }));
const writerUserPrompt = `Reporting period: ${cfg.periodStart.slice(0, 10)} to ${cfg.runDate.slice(0, 10)}\n` +
  `Tracked competitors (include all): ${cfg.competitors.map(c => c.name).join('; ')}\n` +
  `Significance threshold: ${S.significanceThreshold}\n\nDevelopments (JSON):\n${JSON.stringify(writerInput, null, 1)}`;

const first = (responses.length && pair('Build Triage Batches', 0).items || [])[0];
return [{ json: {
  scored, kept, selfMentions, writerUserPrompt, failures,
  triageStats: { nodeVersion: '1.15', scored: scored.length, kept: kept.length, reassigned, socialCapped: scored.filter(s => s.socialCapped).length, notRelevant, llmDuplicates, evidenceMismatch, missingFromAI,
    batches: responses.length, batchFailures: failures.length },
  pipelineStats: (first && first.pipelineStats) || null,
} }];

// Pick high-significance items whose URL is a direct article link and request full text.
const cfg = $('Config').first().json;
const T = cfg.settings.tavily || {};
const base = $('Score & Validate').first().json;
const urls = [];
if (T.enabled) {
  for (const k of base.kept) {
    if (k.significance < T.enrichMinSignificance) continue;
    const cands = [k.url, ...(k.alsoReportedBy || []).map(a => a.url)].filter(u => u && !/news\.google\.com/.test(u));
    if (cands.length) urls.push({ id: k.id, url: cands[0] });
    if (urls.length >= T.maxEnrich) break;
  }
}
return [{ json: { enrichTargets: urls, body: { urls: urls.map(u => u.url), extract_depth: 'basic' }, doEnrich: urls.length > 0 } }];

// Attach full-article excerpts to the writer input. Falls back silently if extraction failed.
const cfg = $('Config').first().json;
const base = $('Score & Validate').first().json;
const req = $('Build Extract Request').first().json;
const r = $input.first().json || {};
const byUrl = new Map();
for (const x of (Array.isArray(r.results) ? r.results : [])) if (x.url && x.raw_content) byUrl.set(x.url, x.raw_content);
const clean = t => String(t).replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/[#*_>`|]+/g, ' ').replace(/\s+/g, ' ').trim();
const excerpts = {};
for (const t of req.enrichTargets) {
  const raw = byUrl.get(t.url) || [...byUrl.entries()].find(([u]) => u.replace(/\/$/, '') === t.url.replace(/\/$/, ''))?.[1];
  if (raw) excerpts[t.id] = clean(raw).slice(0, 1800);
}
const writerInput = base.kept.map(k => ({ id: k.id, competitor: k.competitorName, category: k.category, significance: k.significance,
  summary: k.summary, implication: k.implication, publisher: k.publisher, date: (k.publishedAt || '').slice(0, 10),
