const cfg = $('Config').first().json;
const base = $('Score & Validate').first().json;
const r = $input.first().json || {};
const strip = s => String(s || '').replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
const keptById = new Map(base.kept.map(k => [k.id, k]));
