let report = null, writerError = null;
try { report = JSON.parse(strip(r.choices[0].message.content)); if (!report || typeof report !== 'object') throw new Error('not an object'); }
catch (e) { writerError = (r.error && (r.error.message || JSON.stringify(r.error))) || e.message; }

function devFromItem(k) {
  return { id: k.id, related_ids: [], headline: k.title.slice(0, 110), what_happened: k.summary,
