  const found = compByName.get(c.name.toLowerCase()) || asArr(report.competitors).find(x => String(x.name || '').toLowerCase().includes(c.name.split(' ')[0].toLowerCase()));
  const sec = found ? { ...found, name: c.name } : { name: c.name, activity_level: 'none', summary: 'No significant developments detected this period.', developments: [] };
  sec.developments = asArr(sec.developments).filter(d => ok(d.id)).map(d => ({ ...d, related_ids: asArr(d.related_ids).filter(ok) }));
  // coverage guard: every verified item above threshold must appear in the report
  const covered = new Set(sec.developments.flatMap(d => [d.id, ...d.related_ids]));
