  for (const k of base.kept.filter(k => k.competitorId === c.id && k.significance >= 4 && !covered.has(k.id))) {
    sec.developments.push(devFromItem(k)); reinserted++; reinsertedHigh++;
  }
  if (sec.developments.length && (!sec.activity_level || sec.activity_level === 'none')) sec.activity_level = 'low';
  if (!found && sec.developments.length) sec.summary = 'Developments listed below (added by coverage check).';
