for (const sec of report.competitors) {
  sec.developments = sec.developments.filter(d => {
    const t = toks(d.headline + ' ' + d.what_happened);
    const txt = d.headline + ' ' + d.what_happened;
    const names = cfg.competitors.filter(c => c.aliases.some(a => new RegExp('\\b' + a.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(txt))).map(c => c.name);
