<table style="width:100%;border-collapse:collapse;font-size:12px">${checks.map(c => `<tr><td style="padding:5px;border:1px solid #eaecf0;width:24px">${c.pass ? '✅' : '⚠️'}</td><td style="padding:5px;border:1px solid #eaecf0">${esc(c.name)}</td><td style="padding:5px;border:1px solid #eaecf0;color:#475467">${esc(c.detail)}</td></tr>`).join('')}</table>
${((base.failures || []).length || $input.first().json.writerError) ? `<p style="font-size:12px;color:#b42318"><b>Errors:</b><br>${[...(base.failures || []).map(f => `Triage batch ${f.batch}: ${esc(String(f.error).slice(0, 300))}`), ...($input.first().json.writerError ? ['Writer: ' + esc(String($input.first().json.writerError).slice(0, 300))] : [])].join('<br>')}</p>` : ''}
<p style="font-size:12px;color:#475467;margin-top:10px">Pipeline: ${esc(pipeline.collected)} collected · ${esc(pipeline.droppedNoise ?? '–')} noise · ${esc(pipeline.droppedOffTopic ?? '–')} off-topic · ${esc(pipeline.droppedStale ?? '–')} stale · ${esc(pipeline.mergedDuplicates ?? '–')} duplicates merged · ${esc(pipeline.skippedSeenInPreviousRuns ?? 0)} seen in earlier runs · ${esc(triageStats.notRelevant)} judged not relevant by AI · ${esc(triageStats.llmDuplicates)} AI-detected duplicates · ${esc(triageStats.reassigned ?? 0)} re-assigned to the correct company · ${esc(triageStats.socialCapped ?? 0)} social posts capped.</p>
<p style="font-size:12px;color:#475467">Sources: ${sourceHealth.map(s => `${s.ok ? '●' : '○'} ${esc(s.label)} (${s.ok ? s.items : esc(s.error)})`).join(' &nbsp; ')}</p>
<p style="font-size:11px;color:#98a2b3;margin-top:18px">Generated automatically from publicly available information. AI-generated summaries — verify against linked sources before external use.</p>
</div></div></body></html>`;

// Markdown version (for Slack/Notion/Docs)
let md = `# ${cfg.settings.reportTitle}\n_${cfg.runSource === 'form' ? 'On-demand' : cfg.settings.cadence} brief · ${period} · ${cfg.runId} · v${cfg.settings.version || ''} (filter v${(pipeline && pipeline.nodeVersion) || 'old'}, scoring v${triageStats.nodeVersion || 'old'}) · QC: ${qcStatus}_\n\n**${report.headline}**\n\n## Executive summary\n` +
  (report.executive_summary.map(b => `- ${b}`).join('\n') || '- No significant developments.') + '\n';
for (const c of report.competitors) {
  md += `\n## ${c.name} — activity: ${c.activity_level || 'none'}\n${c.summary}\n`;
  for (const d of c.developments) { const s = byId.get(d.id) || {};
    md += `\n- **${d.headline}** (sig ${d.significance}/5, ${CAT[d.category] || d.category}) [${d.id}](${s.url || ''})\n  - ${d.what_happened}\n  - _Why it matters:_ ${d.why_it_matters}\n`; }
}
if (selfM.length) md += `\n## Cavli in the news\n${selfM.map(m => `- [${m.title}](${m.url}) — ${[m.publisher, day(m.publishedAt)].filter(Boolean).join(', ')}`).join('\n')}\n`;
if (report.market_signals.length) md += `\n## Market signals\n${report.market_signals.map(m => `- ${m.text}`).join('\n')}\n`;
if (report.recommended_actions.length) md += `\n## Recommended actions\n${report.recommended_actions.map(a => `- [${a.priority}] ${a.action} — ${a.owner} (${a.ids.join(', ')})`).join('\n')}\n`;
if (report.watchlist.length) md += `\n## Watchlist\n${report.watchlist.map(w => `- ${w}`).join('\n')}\n`;
md += `\n---\n## Quality control: ${qcStatus.toUpperCase()}\n${checks.map(c => `- ${c.pass ? '✓' : '✗'} ${c.name} — ${c.detail}`).join('\n')}\n`;
const errList = [...(base.failures || []).map(f => `Triage batch ${f.batch}: ${f.error}`), ...($input.first().json.writerError ? [`Writer: ${$input.first().json.writerError}`] : [])];
if (errList.length) md += `\n### Errors\n${errList.map(e => '- ' + String(e).slice(0, 400)).join('\n')}\n`;

// Commit processed stories to cross-run history — scheduled runs only (manual/test runs never change it)
const runMode = (typeof $execution !== 'undefined' && $execution.mode) || 'production';
// Only scheduled runs write to the memory; manual and form runs never change it
const store = (runMode === 'test' || runMode === 'manual' || cfg.runSource !== 'schedule') ? {} : $getWorkflowStaticData('global');
const seen = store.seenStories || {};
const nowMs = Date.now(), ttl = cfg.settings.historyRetentionDays * 86400000;
for (const s of base.scored) seen[s.dedupeKey] = nowMs;
for (const [k, t] of Object.entries(seen)) if (nowMs - t > ttl) delete seen[k];
store.seenStories = seen;

const fname = `competitor-intel_${day(cfg.runDate)}`;
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
return [{
  json: {
    qcStatus, subject: `${qcStatus === 'pass' ? '' : '[REVIEW] '}${cfg.settings.reportTitle} · ${period}`,
    headline: report.headline, html: h, markdown: md, fileName: fname,
    recipients: cfg.settings.reportRecipients, reviewer: cfg.settings.reviewerEmail,
    runId: cfg.runId, developments: totalDev, checks,
  },
  binary: {
    report_html: { data: b64(h), mimeType: 'text/html', fileName: fname + '.html', fileExtension: 'html' },
    report_md: { data: b64(md), mimeType: 'text/markdown', fileName: fname + '.md', fileExtension: 'md' },
  },
}];

